/**
 * Legacy flat keys that are edited elsewhere in the theme editor (Text & Translations › System Labels,
 * Products › Badges). They keep a default here but are intentionally not listed in COPY_SCHEMA, so
 * the Content panel never shows two inputs for one string.
 */
export const FLAT_COPY_DEFAULTS: Record<string, string> = {
  cartLabel: "Bag",
  soldOutLabel: "Sold Out",
  saleBadgeLabel: "Sale",
};

// Flat key → default lookup, derived once from the schema.
export const DEFAULT_COPY: Record<string, string> = COPY_SCHEMA.reduce(
  (acc, g) => {
    for (const f of g.fields) acc[f.key] = f.default;
    return acc;
  },
  { ...FLAT_COPY_DEFAULTS } as Record<string, string>,
);

/** Unexpanded copy for authoring: editing a default must retain {year}/{name} tokens. */
/**
 * Shop text a storefront part shows when Text & labels has no override for it — today the footer's About
 * blurb, which falls back to Settings › General's shop description. Studio's Text & labels shows the same
 * words as its default, so "Using default" matches what shoppers see.
 */
export function shopCopyFallback(settings: any, key: string): string | undefined {
  if (key === "footerAbout") return settings?.info?.description || undefined;
  return undefined;
}

export function getCopyTemplate(design: any, key: string): string {
  const override = design?.copy?.[key];
  if (typeof override === "string") return override;
  const legacy = design?.[key];
  return (typeof legacy === "string" && legacy ? legacy : DEFAULT_COPY[key]) || "";
}

/**
 * Resolve a shopper-facing string. Order of precedence:
 *   design.copy[key]  →  design[key] (legacy flat)  →  schema default.
 * Supports {year} token replacement and optional extra vars.
 */
export function getCopy(design: any, key: string, vars?: Record<string, string | number>): string {
  const raw = getCopyTemplate(design, key);
  const all: Record<string, string | number> = { year: new Date().getFullYear(), ...(vars || {}) };
  // {name} is the site name (Text & labels › Site & sharing) in every string that mentions it.
  if (!("name" in all) && key !== "siteName" && raw.includes("{name}")) all.name = getCopy(design, "siteName");
  return raw.replace(/\{(\w+)\}/g, (m: string, name: string) =>
    name in all ? String(all[name]) : m,
  );
}

/** Local validation reasons stay editable; provider diagnostics never become shopper copy. */
export class CopyError extends Error {
  constructor(design: any, public key: string, public vars?: Record<string, string | number>) {
    super(getCopy(design, key, vars));
  }
}
export function copyErrorText(error: unknown, design: any, fallback: string): string {
  if (error instanceof AppVerificationError) return getCopy(design, "appVerificationFailed");
  return error instanceof CopyError ? getCopy(design, error.key, error.vars) : getCopy(design, fallback);
}
